// The kind of match event.
type IncidentType string

const (
	// Any score, whether a goal, basket, try, touchdown, …; `detail` gives the kind. Points are not listed for set sports (volleyball, table tennis, badminton); the end of each set appears as a `period` row instead.
	IncidentTypeGoal IncidentType = "goal"
	// A card shown to a team official or a player.
	IncidentTypeCard IncidentType = "card"
	// A substitution in which playerIn comes on for playerOut.
	IncidentTypeSubstitution IncidentType = "substitution"
	// The end of a period, and nothing else: since 2026-10-23 a period still in progress gets no row. `period` names the period just finished, and `text` holds its scoreboard label (FT, HT, Q2, 2. set, 3rd period, …). The scores show the match score at that moment — for volleyball, table tennis and badminton the sets won so far; the points inside each set are given by /points and by the fixture’s `periods`.
	IncidentTypePeriod IncidentType = "period"
	// Announcement of added time: `addedMinute` extra minutes following `minute`.
	IncidentTypeInjuryTime IncidentType = "injuryTime"
	// The outcome of a video review, described by `detail`; `confirmed` means the original call was upheld.
	IncidentTypeVarDecision IncidentType = "varDecision"
	// A penalty kick taken during play that did not result in a goal (`detail` missed). A converted penalty is recorded as a `goal` with detail `penalty`.
	IncidentTypeInGamePenalty IncidentType = "inGamePenalty"
	// A single kick in a penalty shoot-out. `shootoutSequence` is its position in the overall order (1, 2, 3, …, counting both sides) and `shootoutRound` is the round, i.e. the 1st, 2nd, … kick of the taker’s side.
	IncidentTypeShootoutPenalty IncidentType = "shootoutPenalty"
	// A time-limited exclusion such as an ice hockey penalty or a handball two-minute suspension, with `durationSeconds` and `reason`.
	IncidentTypeSuspension IncidentType = "suspension"
)

