type SeriesFiguresSource string

const (
	// Taken as published by our data source; null where it provides none.
	SeriesFiguresSourceUpstream SeriesFiguresSource = "upstream"
	// Derived by DataSportsAPI from every race of each completed championship round, since the source only publishes positions and points for some series (MotoGP, IndyCar, WorldSBK and others whose tables lack these columns). wins counts 1st places, podiums top-3 finishes, polePositions starts from grid position 1, racesStarted the races started (for a team, races where at least one of its entries started) and racesWithPoints the races in which points were scored; a team’s figures include all its entries. All races of a round count (WorldSBK's Race 1, Superpole Race and Race 2, since 2026-11-25); sprints (MotoGP, F1) and aborted starts with no winner do not. Without a grid, per-race points or a fastest lap in the races, polePositions, racesWithPoints or fastestLaps respectively read null (WorldSBK has neither grid nor per-race points).
	SeriesFiguresSourceComputed SeriesFiguresSource = "computed"
)

// Coordinate frame used for a fixture’s positions; each sport has its own. Every x / y / z returned by the tracking endpoints uses it.
type TrackingCoordinates string

const (
	// Football: 0–100 along the pitch (x) and across it (y). Home plays towards x = 100 and away towards x = 0 for both halves; the frame does not turn after the break.
	TrackingCoordinatesPitch TrackingCoordinates = "pitch"
	// Tennis: millimetres from the middle of the net. x follows the length of the court (around ±11,900 at each baseline), y its width (around ±4,100 at the doubles sidelines), and z gives how high the ball is above the court surface.
	TrackingCoordinatesTennisCourt TrackingCoordinates = "tennisCourt"
	// Basketball: 0–100 along the court (x) and across it (y). Home shoots at the x = 100 basket and away at the x = 0 one for the whole game; where the source swaps baskets at half-time, timeline positions are converted into this frame. Since 2026-11-27 timeline y is given as 100 minus the source's figure, because the source measures it from the other sideline than its tracked events; tracked events, timeline entries and the ball therefore agree on y.
	TrackingCoordinatesCourt TrackingCoordinates = "court"
	// Ice hockey: 0–100 along the rink (x) and across it (y). Home attacks the x = 100 goal and away the x = 0 goal in every period. Which end each team really defended changes by period and the source does not report it, so since 2026-11-12 each side’s positions are mirrored per period according to where its shots went.
	TrackingCoordinatesRink TrackingCoordinates = "rink"
	// American football (since 2026-11-24): yards along the field, 0 at the home goal line and 100 at the away one, for the whole game, so 50 is midfield; the end zones run from −10 to 0 and from 100 to 110. Player frames (since 2026-11-26) add y, 0–100 across the field. Timeline positions stay null; a play’s spot is in TimelineEvent.americanFootball.spot.
	TrackingCoordinatesField TrackingCoordinates = "field"
	// Darts (since 2026-11-13): there are no positions at all, so every position is null. Each throw tells you which bed it hit instead (TimelineEvent.darts).
	TrackingCoordinatesNone TrackingCoordinates = "none"
)

// Which scoring area of the board a dart hit.
type DartsRing string

const (
	// A single bed: the segment’s number counts once.
	DartsRingSingle DartsRing = "single"
	// The narrow outer ring: the number counts twice. Every leg has to be finished on a double.
	DartsRingDouble DartsRing = "double"
	// The narrow inner ring: the number counts three times.
	DartsRingTreble DartsRing = "treble"
	// The ring around the bullseye, worth 25.
	DartsRingOuterBull DartsRing = "outerBull"
	// The bullseye itself, worth 50; it counts as a double.
	DartsRingBull DartsRing = "bull"
	// Scores 0: the dart landed outside the scoring area or bounced out.
	DartsRingMiss DartsRing = "miss"
)

// For a dart in a single, which of the two single beds it hit.
type DartsBed string

const (
	// The single bed nearer the centre, from the outer bull out to the treble ring.
	DartsBedInner DartsBed = "inner"
	// The single bed nearer the edge, from the treble ring out to the double ring.
	DartsBedOuter DartsBed = "outer"
)

// What a table tennis point brought about (TimelineTableTennis.flag). Since 2026-11-24.
type TableTennisPointFlag string

const (
	// After this point one player can win the game with the next.
	TableTennisPointFlagGamePoint TableTennisPointFlag = "gamePoint"
	// After this point one player can win the match with the next.
	TableTennisPointFlagMatchPoint TableTennisPointFlag = "matchPoint"
	// This point won the game.
	TableTennisPointFlagGameWon TableTennisPointFlag = "gameWon"
	// This point won the match.
	TableTennisPointFlagMatchWon TableTennisPointFlag = "matchWon"
)

// How an American football play ended (TimelineAmericanFootball.outcome). Each value belongs to the play types named before the colon. Since 2026-11-24.
type AmericanFootballOutcome string

const (
	// pass: caught; rush: the runner was stopped in play.
	AmericanFootballOutcomeComplete AmericanFootballOutcome = "complete"
	// pass: not caught.
	AmericanFootballOutcomeIncomplete AmericanFootballOutcome = "incomplete"
	// kickoff / punt: the receiving team ran it back.
	AmericanFootballOutcomeReturned AmericanFootballOutcome = "returned"
	// kickoff / punt (or a run): dead in the end zone, so play restarts at the receiving team’s own 20 or 25.
	AmericanFootballOutcomeTouchback AmericanFootballOutcome = "touchback"
	// punt: caught with no return attempted.
	AmericanFootballOutcomeFairCatch AmericanFootballOutcome = "fairCatch"
	// kickoff / punt: stopped by the kicking team where it came to rest.
	AmericanFootballOutcomeDowned AmericanFootballOutcome = "downed"
	// kickoff / punt: went out of bounds.
	AmericanFootballOutcomeOutOfBounds AmericanFootballOutcome = "outOfBounds"
	// kickoff / punt: the receiver could not hold on to it.
	AmericanFootballOutcomeMuffed AmericanFootballOutcome = "muffed"
	// fieldGoal / extraPoint / twoPointConversion: successful.
	AmericanFootballOutcomeMade AmericanFootballOutcome = "made"
	// fieldGoal / extraPoint / twoPointConversion: unsuccessful.
	AmericanFootballOutcomeMissed AmericanFootballOutcome = "missed"
	// fumble: the team that fumbled got the ball back.
	AmericanFootballOutcomeRecovered AmericanFootballOutcome = "recovered"
	// fumble: the opponents took the ball.
	AmericanFootballOutcomeTurnover AmericanFootballOutcome = "turnover"
	// penalty: enforced.
	AmericanFootballOutcomeAccepted AmericanFootballOutcome = "accepted"
	// penalty: turned down by the team it would have helped.
	AmericanFootballOutcomeDeclined AmericanFootballOutcome = "declined"
	// penalty: fouls by both teams cancel each other out.
	AmericanFootballOutcomeOffsetting AmericanFootballOutcome = "offsetting"
	// videoReview / challenge: the call on the field stays.
	AmericanFootballOutcomeCallStands AmericanFootballOutcome = "callStands"
	// videoReview / challenge: the call on the field was changed.
	AmericanFootballOutcomeCallOverturned AmericanFootballOutcome = "callOverturned"
	// touchdown: a pass into the end zone.
	AmericanFootballOutcomePassing AmericanFootballOutcome = "passing"
	// touchdown: scored on a run.
	AmericanFootballOutcomeRushing AmericanFootballOutcome = "rushing"
	// touchdown: an intercepted pass carried back.
	AmericanFootballOutcomeInterceptionReturn AmericanFootballOutcome = "interceptionReturn"
	// touchdown: a kickoff carried back.
	AmericanFootballOutcomeKickoffReturn AmericanFootballOutcome = "kickoffReturn"
	// touchdown: a punt carried back.
	AmericanFootballOutcomePuntReturn AmericanFootballOutcome = "puntReturn"
	// touchdown: a recovered fumble carried back.
	AmericanFootballOutcomeFumbleReturn AmericanFootballOutcome = "fumbleReturn"
	// An outcome the source names that we have not mapped yet.
	AmericanFootballOutcomeOther AmericanFootballOutcome = "other"
)

// The part a player took in an American football play, as AmericanFootballPlayer.role records it. Since 2026-11-24.
type AmericanFootballRole string

const (
	// Threw the pass; also the quarterback who was sacked.
	AmericanFootballRolePasser AmericanFootballRole = "passer"
	// Caught the pass.
	AmericanFootballRoleReceiver AmericanFootballRole = "receiver"
	// The intended receiver of a pass that was not caught.
	AmericanFootballRoleTarget AmericanFootballRole = "target"
	// Carried the ball.
	AmericanFootballRoleRusher AmericanFootballRole = "rusher"
	// Took the kick: kickoff, punt, field goal or extra point.
	AmericanFootballRoleKicker AmericanFootballRole = "kicker"
	// Fielded the kick.
	AmericanFootballRoleReturner AmericanFootballRole = "returner"
	// Made the tackle.
	AmericanFootballRoleTackler AmericanFootballRole = "tackler"
	// Sacked the quarterback.
	AmericanFootballRoleSacker AmericanFootballRole = "sacker"
	// Picked off the pass.
	AmericanFootballRoleInterceptor AmericanFootballRole = "interceptor"
	// Lost the ball.
	AmericanFootballRoleFumbler AmericanFootballRole = "fumbler"
	// Came up with the loose ball.
	AmericanFootballRoleRecoverer AmericanFootballRole = "recoverer"
	// Broke up the pass.
	AmericanFootballRoleDefender AmericanFootballRole = "defender"
	// Blocked the kick.
	AmericanFootballRoleBlocker AmericanFootballRole = "blocker"
	// Scored, as on a safety.
	AmericanFootballRoleScorer AmericanFootballRole = "scorer"
)

// How a timelineEvent frame changes the timeline you keep.
type TimelineOp string

const (
	// Insert the event, or overwrite the one you already hold under that key, because the source corrected it or because its position was flipped into the home → x = 100 frame after more shots of that period came in.
	TimelineOpUpsert TimelineOp = "upsert"
	// Delete the event with this key, because the source took it back (a goal that was chalked off, a shot logged twice).
	TimelineOpRemove TimelineOp = "remove"
)

