// Codes that a WebSocket `error` frame can carry.
type WsErrorCode string

const (
	// The frame is not valid JSON, does not match any known shape, or is missing a required field; `message` names that field (e.g. "channel: required").
	WsErrorCodeBadFrame WsErrorCode = "bad_frame"
	// The channel name is not one we offer, or its sport slug is unknown.
	WsErrorCodeUnknownChannel WsErrorCode = "unknown_channel"
	// Your plan’s tier does not include this channel.
	WsErrorCodeChannelForbidden WsErrorCode = "channel_forbidden"
	// league:{id} refers to a league id DataSportsAPI never issued (take ids from /v2/leagues or from a fixture’s league). The REST API returns 404 not_found for the same id.
	WsErrorCodeUnknownLeague WsErrorCode = "unknown_league"
	// The id in fixture:{id} — or in odds:{id} (from 2026-11-04) or tracking:{id} (from 2026-11-12) — is not a fixture DataSportsAPI issued; REST answers 404 not_found for that id. It does not count as one of your channels.
	WsErrorCodeUnknownFixture WsErrorCode = "unknown_fixture"
	// race:{id} does not point to a race: it is a season or session id, or an id DataSportsAPI never issued. /v2/races/{id} returns 404 for the same id. It does not count as one of your channels.
	WsErrorCodeUnknownRace WsErrorCode = "unknown_race"
	// team:{id} refers to a team id DataSportsAPI never issued (take ids from a fixture’s home / away or from /v2/teams). The REST API returns 404 not_found for the same id. Available since 2026-11-04.
	WsErrorCodeUnknownTeam WsErrorCode = "unknown_team"
	// You subscribed to fixture:{id}, odds:{id}, tracking:{id} or race:{id} for a match that kicked off, or a race that began, before the first day of your plan's history; `message` names that day. A REST call for that id gets 403 history_not_in_plan too. A refused channel is left out of maxChannels. Available since 2026-11-27.
	WsErrorCodeHistoryNotInPlan WsErrorCode = "history_not_in_plan"
	// A resync / unsubscribe targeted a channel this connection has not joined.
	WsErrorCodeNotSubscribed WsErrorCode = "not_subscribed"
	// This connection has reached its maxChannels limit.
	WsErrorCodeTooManyChannels WsErrorCode = "too_many_channels"
	// Building the snapshot failed; retry with resync. For league:{id}, this also happens when the league id could not be verified at that moment, in which case subscribe again.
	WsErrorCodeSnapshotFailed WsErrorCode = "snapshot_failed"
	// This connection sent over 60 frames within 10 seconds; further frames are discarded until the window resets.
	WsErrorCodeRateLimited WsErrorCode = "rate_limited"
)

// periodN: Regulation period number N. What a period is depends on the sport: a half in football, rugby, handball, futsal, minifootball and bandy; a quarter in basketball, American football, water polo and aussie rules; a period in ice hockey and floorball; a set in tennis, volleyball, table tennis, badminton and padel; an inning in baseball; a round in combat sports; a map / game in esports; a leg / frame block in darts and snooker. inningN: Cricket only: innings number N. extra1: Football and futsal: the opening half of extra time. extra2: Football and futsal: the closing half of extra time. overtime: Every overtime period summed into one value (American football, basketball, handball, ice hockey, water polo, …), as used by scores, status.period and incidents. In baseball it holds the runs scored in extra innings, and only when the source provides no inning-by-inning split (period10, …). overtimeN: Overtime number N, where the source numbers them separately (since 2026-11-23): in match statistics, in play by play and on ice hockey shots. A single overtime is still overtime1, and a basketball game that needs two has overtime1 and overtime2. Scores, status.period and incidents keep the combined `overtime`. penalties: The penalty shoot-out, which appears only as a `status.period` value; its score is kept in ScoreSide.penalties, not under a `periods` key.
type PeriodKey string

